  ('GL-A3', 'Financial Account', 1, '{"format":1,"code":"GL-A3","slug":"fin","title":"Financial Account","sub":"One sheet per account. Bank, investment, retirement, annuity, insurance, and digital assets.","accent":"gold","matter":[{"type":"text","key":"m_f01","label":"Matter / case name","w":3},{"type":"text","key":"m_f02","label":"Case no.","w":1},{"type":"text","key":"m_f03","label":"County","w":2},{"type":"choice","key":"m_f04","label":"Matter type","w":3,"multi":false,"options":[{"key":"opt1","label":"Guardianship"},{"key":"opt2","label":"Estate"},{"key":"opt3","label":"Trust"},{"key":"opt4","label":"Other"}]},{"type":"choice","key":"m_f05","label":"Our role","w":3,"multi":false,"options":[{"key":"opt1","label":"Guardian of estate"},{"key":"opt2","label":"Fiduciary / administrator"},{"key":"opt3","label":"Counsel"},{"key":"opt4","label":"Trustee"}]},{"type":"text","key":"m_f06","label":"Ward / decedent","w":2},{"type":"text","key":"m_f07","label":"Date of death or appointment","w":2,"hint":"This is the valuation date for the inventory."},{"type":"text","key":"m_f08","label":"Assigned staff","w":2}],"first":{"type":"tasks","key":"first","label":"Do first (done)","options":[{"key":"opt1","label":"Notify the institution and submit our letters of authority"},{"key":"opt2","label":"Shut off outside access: cards, online banking, checks, any POA agent"},{"key":"opt3","label":"Get the balance on the date of death or appointment (the inventory number)"},{"key":"opt4","label":"List every automatic deposit and automatic payment"},{"key":"opt5","label":"Look back 12 months for large or unusual withdrawals or changes"}]},"sections":[{"key":"s01","n":1,"title":"What kind of asset","rows":[{"type":"choice","key":"s01_f01","label":"Bank","w":6,"multi":false,"options":[{"key":"opt1","label":"Checking"},{"key":"opt2","label":"Savings"},{"key":"opt3","label":"Money market"},{"key":"opt4","label":"CD"}]},{"type":"choice","key":"s01_f02","label":"Investment","w":6,"multi":false,"o