nager / advisor firm","w":3},{"type":"text","key":"s02_f04","label":"Advisor name, phone, email","w":3},{"type":"text","key":"s02_f05","label":"Brand or name the family uses, if different","w":3},{"type":"text","key":"s02_f06","label":"Branch or local office","w":3},{"type":"choice","key":"s02_f07","label":"Statements go to","w":4,"multi":false,"options":[{"key":"opt1","label":"Home address"},{"key":"opt2","label":"Email"},{"key":"opt3","label":"Advisor"},{"key":"opt4","label":"Firm"},{"key":"opt5","label":"Unknown"}]},{"type":"choice","key":"s02_f08","label":"Address changed to firm","w":2,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"Unknown"}]}]},{"key":"s03","n":3,"title":"Account details and ownership","rows":[{"type":"text","key":"s03_f01","label":"Account number (last 4 only)","w":2},{"type":"text","key":"s03_f02","label":"Full number is stored in","w":4,"hint":"The secure file or BusinessMap. Never on this sheet."},{"type":"text","key":"s03_f03","label":"Account title, exactly as it appears on the statement","w":6},{"type":"choice","key":"s03_f04","label":"Ownership","w":6,"multi":true,"options":[{"key":"opt1","label":"Sole"},{"key":"opt2","label":"Joint with survivorship"},{"key":"opt3","label":"POD"},{"key":"opt4","label":"TOD"},{"key":"opt5","label":"Trust-owned"},{"key":"opt6","label":"Guardianship account"},{"key":"opt7","label":"Estate account"},{"key":"opt8","label":"Custodial (UTMA)"},{"key":"opt9","label":"SSA rep payee"}]},{"type":"text","key":"s03_f05","label":"Other owner(s) on the account","w":3},{"type":"text","key":"s03_f06","label":"Authorized signers / POA agent","w":3},{"type":"choice","key":"s03_f07","label":"Beneficiary designation","w":2,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"Unknown"}]},{"type":"text","key":"s03_f08","label":"Beneficiaries and percentages","w":4},{"type":"choice","key":"s03_f09","label":"Confirmed in writing by the institution","w":6,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"Unknown"}]},{"type":"warn","html":"Joint, POD, TOD, and beneficiary-designated accounts may pass outside probate, and in a guardianship a joint owner may claim the money is theirs. Do not assume either way. Record exactly what the institution says and flag it to the attorney."}]},{"key":"s04","n":4,"title":"Balance and value","rows":[{"type":"text","key":"s04_f01","label":"Balance on date of death / appointment","w":3,"hint":"This is the inventory value."},{"type":"text","key":"s04_f02","label":"Source of that balance","w":3},{"type":"text","key":"s04_f03","label":"Latest balance","w":2},{"type":"text","key":"s04_f04","label":"As-of date","w":2},{"type":"choice","key":"s04_f05","label":"Source","w":2,"multi":false,"options":[{"key":"opt1","label":"Statement"},{"key":"opt2","label":"Letter"},{"key":"opt3","label":"Online"},{"key":"opt4","label":"Verbal only"}]},{"type":"textarea","key":"s04_f06","label":"Holdings (positions, CD rate and maturity, bond maturities, policy face value)","rows":2},{"type":"choice","key":"s04_f07","label":"CD auto-renews","w":2,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"N/A"}]},{"type":"choice","key":"s04_f08","label":"Cost basis available","w":2,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"Unknown"}]},{"type":"choice","key":"s04_f09","label":"Loan or margin against it","w":2,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"Unknown"}]}]},{"key":"s05","n":5,"title":"Cards, checks, and outside access","rows":[{"type":"choice","key":"s05_f01","label":"Account frozen","w":3,"multi":false,"options":[{"key":"opt1","label":"Yes"},{"key":"opt2","label":"No"},{"key":"opt3","label":"Unknown"}]},{"type":"choice","key":"s05_f02","label"